#include <iostream>
using namespace std;

void enqueue(int q[], int& back, int& count, int p) {
    q[back] = p;
    back = (back + 1) % 4;
    count++;
}

int dequeue(int q[], int& front, int& count) {
    int p = q[front];
    front = (front + 1) % 4;
    count--;
    return p;
}

int main() {
    int need[3] = {5, 2, 3};
    int q[4];
    int front = 0;
    int back = 0;
    int count = 0;
    for (int p = 0; p < 3; p++) {
        enqueue(q, back, count, p);
    }
    while (count > 0) {
        int p = dequeue(q, front, count);
        int run = min(2, need[p]);
        need[p] -= run;
        cout << "P" << p << " runs " << run;
        if (need[p] > 0) {
            enqueue(q, back, count, p);
            cout << endl;
        } else {
            cout << " and finishes" << endl;
        }
    }
    return 0;
}
